Берілгені бойынша, ABCD параллелограмм. AC және BD оның екі диагоналі. Векторларды \vec{AB} және \vec{AC} \vec{AD} және \vec{BD} арқылы өрнектеп, келесіні көрсету керек:
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ және } \vec{AC} - \vec{BD} = 2\vec{AB}.

\text{Үшбұрышта } \Delta ABD,
\vec{AD} = \vec{AB} + \vec{BD} \text{ [үшбұрыш ережесі]}
\therefore \vec{AB} = \vec{AD} - \vec{BD} \text{.............(i)}
\text{Тағы да үшбұрышта ACD, } \vec{AC} = \vec{AD} + \vec{DC} \text{[үшбұрыш ережесі]}
\text{[ABCD параллелограмм болғандықтан, } \vec{DC} = \vec{AB}]
= \vec{AD} + \vec{AD} - \vec{BD} [\because \vec{AB} = \vec{AD} - \vec{BD}]
\therefore \vec{AC} = 2\vec{AD} - \vec{BD} \text{.............(ii)}
\text{Енді, } \vec{AC} + \vec{BD} = 2\vec{AD} - \vec{BD} + \vec{BD}
\text{[(ii) теңдеуінің екі жағына } \vec{BD} \text{ қосу арқылы]}
= 2 \vec{AD}
\therefore \vec{AC} + \vec{BD} = 2 \vec{BC} \text{.............(iii)}
\text{[ABCD параллелограмм болғандықтан, } \vec{AD} = \vec{BC}]
\text{Тағы да, } \vec{AC} - \vec{BD} = (2\vec{AD} - \vec{BD}) - \vec{BD} \text{ [(ii) бойынша]}
= 2\vec{AD} - 2 \vec{BD} = 2 (\vec{AD} - \vec{BD})
= 2\vec{AB} \text{ [(i) бойынша]}
\therefore \vec{AC} - \vec{BD} = 2\vec{AB} \text{.............(iv)}
\text{Енді, (i), (ii), (iii) және (iv) теңдеулерінен біз аламыз,}
\vec{AB} = \vec{AD} - \vec{BD}
\vec{AC} = 2\vec{AD} - \vec{BD}
\vec{AC} + \vec{BD} = 2\vec{BC} \text{ және } \vec{AC} - \vec{BD} = 2\vec{AB} \text{ (Көрсетілді)}

